// Baseline: the v1 schema, written out by hand (not generated by drizzle-kit, whose
// first migration would fail on a database that already has these tables).
//
// Everything is idempotent. The DDL is legacy/schema.js SCHEMA_SQL verbatim (all
// IF NOT EXISTS), so a fresh database gets the same sqlite_master text v1 would
// have written. The three tickets columns v1 added later are applied the same two
// step way v1 does, but each ALTER is guarded by PRAGMA table_info because SQLite
// has no ADD COLUMN IF NOT EXISTS. Keeping the ALTERs out of the CREATE is what
// keeps sqlite_master identical to a v1-created database.
import type Database from 'better-sqlite3';
import type { Migration } from '../migrate.js';

export const BASELINE_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  password TEXT NOT NULL,
  is_admin INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS counters (
  prefix TEXT PRIMARY KEY,
  next INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS tickets (
  id INTEGER PRIMARY KEY,
  project_slug TEXT NOT NULL,
  board_slug TEXT NOT NULL,
  key TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  type TEXT NOT NULL,
  status TEXT NOT NULL,
  assignee TEXT,
  qa_owner TEXT,
  parent_key TEXT,
  level TEXT,
  description TEXT,
  acceptance_criteria TEXT,
  points INTEGER,
  appetite TEXT,
  sprint_id TEXT,
  blocked INTEGER DEFAULT 0,
  blocker_reason TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_tickets_board ON tickets(project_slug, board_slug);
CREATE INDEX IF NOT EXISTS idx_tickets_assignee ON tickets(assignee);
CREATE INDEX IF NOT EXISTS idx_tickets_sprint ON tickets(sprint_id);
CREATE INDEX IF NOT EXISTS idx_tickets_parent ON tickets(parent_key);

CREATE TABLE IF NOT EXISTS comments (
  id INTEGER PRIMARY KEY,
  ticket_key TEXT NOT NULL,
  author TEXT NOT NULL,
  body TEXT NOT NULL,
  source TEXT DEFAULT 'user',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_comments_ticket ON comments(ticket_key);

CREATE TABLE IF NOT EXISTS github_links (
  id TEXT PRIMARY KEY,
  ticket_key TEXT NOT NULL,
  kind TEXT NOT NULL,
  repo TEXT NOT NULL,
  ref TEXT NOT NULL,
  url TEXT,
  actor TEXT,
  environment TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_github_links_ticket ON github_links(ticket_key);

CREATE TABLE IF NOT EXISTS project_docs (
  id TEXT PRIMARY KEY,
  project_slug TEXT NOT NULL,
  title TEXT NOT NULL,
  kind TEXT NOT NULL,
  url TEXT,
  body TEXT,
  author TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS project_files (
  id TEXT PRIMARY KEY,
  project_slug TEXT NOT NULL,
  original_name TEXT NOT NULL,
  stored_path TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  mime_type TEXT,
  uploaded_by TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS ticket_links (
  id TEXT PRIMARY KEY,
  ticket_key TEXT NOT NULL,
  title TEXT NOT NULL,
  url TEXT NOT NULL,
  author TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS ticket_files (
  id TEXT PRIMARY KEY,
  ticket_key TEXT NOT NULL,
  original_name TEXT NOT NULL,
  stored_path TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  mime_type TEXT,
  uploaded_by TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS sprints (
  id TEXT PRIMARY KEY,
  project_slug TEXT NOT NULL,
  board_slug TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL,
  start_date TEXT,
  end_date TEXT,
  status TEXT DEFAULT 'planned',
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS retros (
  id TEXT PRIMARY KEY,
  project_slug TEXT NOT NULL,
  board_slug TEXT NOT NULL,
  sprint_id TEXT,
  name TEXT NOT NULL,
  status TEXT DEFAULT 'open',
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS retro_cards (
  id TEXT PRIMARY KEY,
  retro_id TEXT NOT NULL,
  column_name TEXT NOT NULL,
  body TEXT NOT NULL,
  author TEXT NOT NULL,
  ticket_key TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE IF NOT EXISTS board_settings (
  project_slug TEXT NOT NULL,
  board_slug TEXT NOT NULL,
  flow TEXT DEFAULT 'kanban',
  agile_enabled INTEGER DEFAULT 0,
  wip_limits TEXT,
  definition_of_done TEXT,
  definition_of_ready TEXT,
  PRIMARY KEY(project_slug, board_slug)
);

CREATE TABLE IF NOT EXISTS ticket_dod (
  ticket_key TEXT NOT NULL,
  item TEXT NOT NULL,
  done INTEGER DEFAULT 0,
  PRIMARY KEY(ticket_key, item)
);
`;

/** Columns v1 added after 1.0. All nullable, so rows written before stay valid. */
export const TICKET_EXTRA_COLUMNS: ReadonlyArray<readonly [name: string, type: string]> = [
  ['priority', 'TEXT'],
  ['labels', 'TEXT'],
  ['due_date', 'TEXT'],
];

export function addMissingColumns(
  db: Database.Database,
  table: string,
  columns: ReadonlyArray<readonly [name: string, type: string]>,
): void {
  const have = new Set(
    (db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>).map((c) => c.name),
  );
  for (const [name, type] of columns) {
    if (!have.has(name)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${name} ${type}`);
  }
}

export const baseline: Migration = {
  name: '0000-baseline',
  up(db) {
    db.exec(BASELINE_SQL);
    addMissingColumns(db, 'tickets', TICKET_EXTRA_COLUMNS);
  },
};
